<script setup lang="ts">
import { NCheckbox, NFormItem, NInputNumber, NButton, NSelect } from 'naive-ui';
import type { ScoreExpectation } from '@problemforge/contracts';
const props=defineProps<{modelValue:ScoreExpectation|null;groups:string[];disabled:boolean}>();
const emit=defineEmits<{'update:modelValue':[value:ScoreExpectation|null]}>();
function change(mutate:(e:ScoreExpectation)=>void){const value=JSON.parse(JSON.stringify(props.modelValue??{groups:[]}));mutate(value);emit('update:modelValue',value);}
</script>
<template><div class="score-expectation"><NCheckbox :checked="!!modelValue" :disabled="disabled" @update:checked="v=>emit('update:modelValue',v?{total:{min:0,max:0},groups:[]}:null)">按组 / 总分范围验收（部分分模式）</NCheckbox><template v-if="modelValue"><div class="judge-form-grid"><NFormItem label="总分范围"><NCheckbox :checked="!!modelValue.total" :disabled="disabled" @update:checked="v=>change(e=>{if(v)e.total={min:0,max:0};else delete e.total;})">检查总分</NCheckbox></NFormItem><NFormItem v-if="modelValue.total" label="总分下限 / 上限"><NInputNumber :value="modelValue.total.min" :min="0" :max="10000" :precision="3" :disabled="disabled" @update:value="v=>change(e=>e.total!.min=v??0)"/><NInputNumber :value="modelValue.total.max" :min="0" :max="10000" :precision="3" :disabled="disabled" @update:value="v=>change(e=>e.total!.max=v??0)"/></NFormItem></div><div v-for="(g,index) in modelValue.groups" :key="index" class="report-actions"><NSelect :value="g.groupId" :options="groups.map(g=>({label:g,value:g}))" :disabled="disabled" style="width:180px" @update:value="v=>change(e=>e.groups[index].groupId=v)"/><NInputNumber :value="g.min" :min="0" :max="10000" :disabled="disabled" aria-label="组分下限" @update:value="v=>change(e=>e.groups[index].min=v??0)"/><NInputNumber :value="g.max" :min="0" :max="10000" :disabled="disabled" aria-label="组分上限" @update:value="v=>change(e=>e.groups[index].max=v??0)"/><NButton :disabled="disabled" @click="change(e=>e.groups.splice(index,1))">移除</NButton></div><NButton :disabled="disabled || !groups.length" @click="change(e=>e.groups.push({groupId:groups[0],min:0,max:0}))">添加组分预期</NButton></template></div></template>
